/* CSS PART 2 OF 2 */

/* Contact and conversion */
.contact-section {
  padding-block: clamp(76px, 10vw, 125px);
  background: var(--sand);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(45px, 8vw, 105px);
}

.contact-intro h2 {
  margin-bottom: 22px;
}

.contact-intro > p {
  max-width: 420px;
}

.contact-details {
  display: flex;
  flex-direction: column;
  gap: 17px;
  margin-top: 32px;
}

.contact-detail {
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--navy);
  font-size: 0.94rem;
  font-weight: 750;
}

.contact-detail-icon {
  display: grid;
  width: 43px;
  height: 43px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(35, 59, 64, 0.2);
  color: var(--orange-dark);
}

.contact-detail small {
  display: block;
  color: var(--ink-soft);
  font-size: 0.7rem;
  font-weight: 600;
}

.contact-form-wrap {
  padding: clamp(26px, 4vw, 48px);
  background: var(--white);
  box-shadow: var(--shadow);
}

.contact-form-wrap h3 {
  margin-bottom: 8px;
  font-size: 1.8rem;
}

.contact-form-wrap > p {
  margin-bottom: 27px;
  font-size: 0.88rem;
}

.contact-form {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 19px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--navy);
  font-size: 0.78rem;
  font-weight: 750;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-width: 0;
  min-height: 49px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: #fff;
  color: var(--ink);
  font-size: 0.9rem;
}

.form-field textarea {
  min-height: 125px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #777f7e;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--orange-dark);
  outline: 2px solid rgba(198, 108, 62, 0.18);
  outline-offset: 1px;
}

.form-submit {
  grid-column: 1 / -1;
  width: 100%;
  margin-top: 5px;
}

.form-note {
  grid-column: 1 / -1;
  margin: -5px 0 0;
  color: var(--ink-soft);
  font-size: 0.74rem;
}

/* Footer */
.site-footer {
  padding-block: 62px 25px;
  background: var(--navy-deep);
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 50px;
  padding-bottom: 45px;
}

.footer-brand {
  max-width: 390px;
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-caption {
  color: #bdc9c7;
}

.footer-brand p {
  max-width: 340px;
  margin-top: 22px;
  color: #c5d0ce;
  font-size: 0.88rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 18px 30px;
}

.footer-links a {
  color: #e2e8e6;
  font-size: 0.82rem;
  font-weight: 650;
}

.footer-links a:hover {
  color: #e9a27b;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.17);
}

.footer-bottom p {
  margin: 0;
  color: #bdc9c7;
  font-size: 0.73rem;
}

/* Desktop menu button is hidden */
.menu-toggle {
  display: none;
}

/* Large and medium screens */
@media (max-width: 1050px) {
  .header-inner {
    gap: 18px;
  }

  .brand-logo {
    width: 58px;
    height: 58px;
  }

  .main-nav {
    gap: 15px;
  }

  .main-nav a:not(.button) {
    font-size: 0.76rem;
  }

  .header-phone {
    display: none;
  }

  .hero-grid {
    min-height: 570px;
  }

  .hero-content {
    padding-right: 35px;
  }

  .why-layout,
  .roof-guide {
    gap: 45px;
  }
}

/* Tablet layout */
@media (max-width: 760px) {
  :root {
    --gutter: 25px;
  }

  html {
    scroll-padding-top: 75px;
  }

  .section {
    padding-block: 76px;
  }

  .header-inner {
    min-height: 76px;
  }

  .brand-logo {
    width: 52px;
    height: 52px;
  }

  .brand-name {
    font-size: 1rem;
  }

  .brand-caption {
    font-size: 0.57rem;
  }

  /* Accessible mobile navigation */
  .menu-toggle {
    display: flex;
    width: 44px;
    height: 44px;
    flex: 0 0 auto;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 5px;
    padding: 0;
    border: 1px solid var(--line);
    border-radius: 2px;
    background: var(--white);
    color: var(--navy);
    cursor: pointer;
  }

  .menu-toggle span[aria-hidden="true"] {
    display: block;
    width: 20px;
    height: 2px;
    flex: 0 0 2px;
    background-color: currentColor;
  }

  .main-nav {
    display: none;
  }

  .main-nav.is-open {
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    z-index: 20;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: 0;
    max-height: calc(100vh - 76px);
    overflow-y: auto;
    overflow-x: hidden;
    padding: 12px var(--gutter) 22px;
    border-top: 1px solid var(--line);
    background: var(--white);
    box-shadow: 0 15px 25px rgba(25, 45, 50, 0.12);
  }

  .main-nav.is-open a {
    display: block;
    width: 100%;
    max-width: 100%;
    padding: 13px 0;
    overflow-wrap: anywhere;
    border-bottom: 1px solid var(--line);
    font-size: 0.92rem;
  }

  .main-nav.is-open .button {
    justify-content: center;
    margin-top: 14px;
    padding-inline: 18px;
    border: 0;
  }

  .hero-grid {
    grid-template-columns: 1fr;
  }

  .hero-content {
    padding: 78px var(--gutter) 65px;
  }

  .hero h1 {
    max-width: 650px;
    font-size: clamp(2.8rem, 10vw, 4.5rem);
  }

  .hero-media {
    min-height: 350px;
    max-height: 480px;
  }

  .hero-media img {
    min-height: 350px;
  }

  .intro-strip-inner {
    grid-template-columns: 1fr;
    padding-block: 10px;
  }

  .intro-fact,
  .intro-fact:first-child {
    padding: 17px 0;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .intro-fact:last-child {
    border-bottom: 0;
  }

  .why-layout,
  .roof-guide,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .why-copy {
    position: static;
  }

  .roofing-panel {
    grid-template-columns: 1fr;
  }

  .roofing-image {
    min-height: 340px;
    max-height: 460px;
  }

  .roofing-image img {
    min-height: 340px;
  }

  .roofing-content {
    padding: 45px var(--gutter) 55px;
  }

  .projects-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 15px;
  }

  .projects-feature {
    grid-template-columns: 1fr;
  }

  .project-card--featured .project-image img {
    min-height: 340px;
  }

  .project-secondary {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto;
  }

  .project-secondary .project-card {
    display: flex;
    flex-direction: column;
  }

  .project-secondary .project-image img {
    min-height: 200px;
  }

  .project-secondary .project-caption {
    padding: 18px;
  }

  .contact-layout {
    gap: 35px;
  }

  .footer-main {
    flex-direction: column;
    gap: 30px;
  }

  .footer-links {
    justify-content: flex-start;
  }
}

/* Narrow mobile screens */
@media (max-width: 480px) {
  :root {
    --gutter: 20px;
  }

  body {
    font-size: 15px;
  }

  .section {
    padding-block: 62px;
  }

  h2 {
    font-size: 2.35rem;
  }

  .brand {
    gap: 9px;
  }

